UPDATE inventory_sync_snapshot_task
SET task_status = 'SUCCEEDED', completed_at = SYSTIMESTAMP,
    lease_owner_instance_id = NULL, lease_expires_at = NULL,
    last_error_code = NULL, last_error_message = NULL, updated_at = SYSTIMESTAMP
WHERE inventory_sync_run_id = #{runId}
  AND task_type = #{taskType}
  AND task_status = 'RUNNING'
  AND lease_owner_instance_id = #{owner}

UPDATE inventory_sync_snapshot_task
SET task_status = CASE WHEN attempt_count >= max_attempts THEN 'FAILED' ELSE 'RETRY_WAIT' END,
    next_attempt_at = #{nextAttemptAt},
    completed_at = CASE WHEN attempt_count >= max_attempts THEN SYSTIMESTAMP ELSE NULL END,
    lease_owner_instance_id = NULL, lease_expires_at = NULL,
    last_error_code = #{errorCode}, last_error_message = #{errorMessage}, updated_at = SYSTIMESTAMP
WHERE inventory_sync_run_id = #{runId}
  AND task_type = #{taskType}
  AND task_status = 'RUNNING'
  AND lease_owner_instance_id = #{owner}

UPDATE inventory_sync_snapshot_task
SET task_status = 'FAILED', completed_at = SYSTIMESTAMP,
    lease_owner_instance_id = NULL, lease_expires_at = NULL,
    last_error_code = #{errorCode}, last_error_message = #{errorMessage}, updated_at = SYSTIMESTAMP
WHERE inventory_sync_run_id = #{runId}
  AND task_type = #{taskType}
  AND task_status = 'RUNNING'
  AND lease_owner_instance_id = #{owner}
